package net.civeira.phylax.features.document.snippetasset.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.document.snippetasset.domain.SnippetAsset;
import net.civeira.phylax.features.document.snippetasset.domain.gateway.SnippetAssetCursor;
import net.civeira.phylax.features.document.snippetasset.domain.gateway.SnippetAssetFilter;

class SnippetAssetSlider extends Slider<SnippetAsset> {

  /**
   * @autogenerated SlideGenerator
   */
  private final SnippetAssetCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final SnippetAssetFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<SnippetAssetFilter, SnippetAssetCursor, Iterator<SnippetAsset>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  SnippetAssetSlider(final Iterator<SnippetAsset> multi, final int limit,
      final BiFunction<SnippetAssetFilter, SnippetAssetCursor, Iterator<SnippetAsset>> gateway,
      final SnippetAssetFilter filter, final SnippetAssetCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param snippetAssets
   * @param limit
   * @return
   */
  @Override
  public Iterator<SnippetAsset> next(List<SnippetAsset> snippetAssets, int limit) {
    SnippetAsset last = snippetAssets.get(snippetAssets.size() - 1);
    SnippetAssetCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
